svg.script:
const terminal = document.getElementById("terminal");
const loading = document.getElementById("loading");

const target =
  "https://cdn.jsdelivr.net/gh/webstashdude/UBG@latest/thing/code.svg";

const words = [
  "initializing",
  "kernel",
  "system",
  "process",
  "module",
  "runtime",
  "memory",
  "cache",
  "buffer",
  "filesystem",
  "network",
  "socket",
  "connection",
  "request",
  "response",
  "service",
  "daemon",
  "thread",
  "worker",
  "scheduler",
  "environment",
  "variable",
  "package",
  "dependency",
  "resource",
  "loader",
  "renderer",
  "interface",
  "session",
  "terminal",
  "console",
  "stream",
  "input",
  "output",
  "device",
  "driver",
  "mount",
  "volume",
  "directory",
  "permission",
  "process",
  "handle",
  "descriptor",
  "binary",
  "library",
  "runtime",
  "configuration",
  "manifest",
  "index",
  "database",
  "query",
  "packet",
  "route",
  "gateway",
  "protocol",
  "address",
  "resolve",
  "lookup",
  "host",
  "domain",
  "certificate",
  "secure",
  "channel",
  "transfer",
  "download",
  "fetch",
  "streaming",
  "decode",
  "parse",
  "compile",
  "execute",
  "start",
  "check",
  "verify",
  "sync",
  "update",
  "refresh",
  "prepare",
  "allocate",
  "release",
  "connect",
  "mount",
  "load",
  "read",
  "write",
  "open",
  "close",
  "flush",
  "scan",
  "index",
  "resolve",
  "initialize",
  "continue",
  "complete",
  "ready"
];

const redWords = [
  "warning",
  "retry",
  "fallback",
  "timeout",
  "notice",
  "reconnect"
];

let line = 0;

function randomHex(length) {
  let output = "";
  const chars = "0123456789abcdef";

  for (let i = 0; i < length; i++) {
    output += chars[Math.floor(Math.random() * chars.length)];
  }

  return output;
}

function randomWord() {
  return words[Math.floor(Math.random() * words.length)];
}

function makeLine() {
  const t = document.createElementNS(
    "http://www.w3.org/2000/svg",
    "text"
  );

  const indent = Math.floor(Math.random() * 3);

  let message =
    (" ".repeat(indent)) +
    "[" +
    String(line).padStart(4, "0") +
    "] " +
    randomWord() +
    " " +
    randomWord() +
    " " +
    randomWord() +
    " :: " +
    randomHex(8);

  if (Math.random() < 0.035) {
    message =
      "[" +
      String(line).padStart(4, "0") +
      "] " +
      redWords[Math.floor(Math.random() * redWords.length)] +
      " :: " +
      randomHex(12);

    t.setAttribute("class", "red");
  }

  t.setAttribute("x", 18);
  t.setAttribute("y", 22 + (line % 38) * 20);
  t.textContent = message;

  terminal.appendChild(t);

  line++;

  /*
   * Keep the screen constantly filled instead of creating
   * a giant number of SVG nodes.
   */
  while (terminal.children.length > 38) {
    terminal.removeChild(terminal.firstChild);
  }

  /*
   * Move every existing line upward slightly.
   * This creates the fast terminal-scroll effect.
   */
  Array.from(terminal.children).forEach((node, index) => {
    node.setAttribute(
      "y",
      22 + index * 20
    );
  });
}

function startTerminal() {

  /*
   * Begin after 0.5 seconds.
   */
  setTimeout(() => {

    /*
     * Generate lots of terminal output very quickly.
     * Roughly 2.5 seconds of continuous output.
     */
    const stream = setInterval(() => {

      /*
       * Multiple lines per tick makes it intentionally
       * difficult to read.
       */
      for (let i = 0; i < 5; i++) {
        makeLine();
      }

    }, 35);

    /*
     * Stop the terminal stream after ~2.5 seconds.
     */
    setTimeout(() => {

      clearInterval(stream);

      terminal.innerHTML = "";

      loading.style.opacity = "1";

      /*
       * Brief pause on the LOADING screen.
       */
      setTimeout(() => {

        /*
         * Open a blank tab first, then navigate that
         * blank tab to the requested SVG.
         */
        const blank = window.open("about:blank", "_blank");

        if (blank) {
          blank.location.href = target;
        } else {
          /*
           * Fallback if the browser blocks the popup.
           */
          window.location.href = target;
        }

      }, 650);

    }, 2500);

  }, 500);
}

startTerminal();
